    35	import static com.google.common.base.Preconditions.checkArgument;
    36	import static com.google.common.io.Files.toByteArray;
    37	import static com.tngtech.archunit.PublicAPI.Usage.ACCESS;
    38	import static com.tngtech.archunit.PublicAPI.Usage.INHERITANCE;
    39	import static com.tngtech.archunit.library.freeze.FreezingArchRule.ensureUnixLineBreaks;
