    43	/**
    44	 * A text file based implementation of a {@link ViolationStore}.<br>
    45	 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
    46	 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.<br>
    47	 * By default, the layout within the configured store folder will look like:
    48	 * <pre><code>
    49	 * storeFolder
    50	 *   |-- stored.rules (the index file of all stored rules)
    51	 *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
    52	 *   |-- 2186b43a-c24c-417d-bd96-547e2dfdba1c (another rule violation file)
    53	 *   |-- ... (more rule violation files for every rule that has been stored so far)
    54	 * </code></pre>
    55	 * To adjust the strategy how the individual rule violation files are named use the constructor
    56	 * {@link TextFileBasedViolationStore#TextFileBasedViolationStore(RuleViolationFileNameStrategy) TextFileBasedViolationStore(RuleViolationFileNameStrategy)}.<br>
    57	 * This {@link ViolationStore} can be configured through the following properties:
    58	 * <pre><code>
    59	 * default.path=...               # string: the path of the folder where violation files will be stored
    60	 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
    61	 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
    62	 * </code></pre>
    63	 */
    64	@PublicAPI(usage = ACCESS)
    65	public final class TextFileBasedViolationStore implements ViolationStore {
    66	    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
    67	
    68	    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\n");
    69	    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    70	    private static final String STORE_PATH_DEFAULT = "archunit_store";
    71	    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    72	    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    73	    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    74	    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    75	    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    76	
    77	    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
    78	
    79	    private final RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    80	
    81	    private boolean storeCreationAllowed;
    82	    private boolean storeUpdateAllowed;
    83	    private File storeFolder;
    84	    private FileSyncedProperties storedRules;
    85	
    86	    /**
    87	     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s
    88	     *
    89	     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
    90	     */
    91	    public TextFileBasedViolationStore() {
    92	        this(__ -> UUID.randomUUID().toString());
    93	    }
    94	
    95	    /**
    96	     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming
    97	     *
    98	     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
    99	     */
   100	    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
   101	        this.ruleViolationFileNameStrategy = ruleViolationFileNameStrategy;
   102	    }
   103	
   104	    @Override
   105	    public void initialize(Properties properties) {
   106	        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
   107	        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
   108	        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
   109	        storeFolder = new File(path);
   110	        File storedRulesFile = getStoredRulesFile();
   111	        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
   112	        storedRules = getOrCreateStoredRules(storedRulesFile);
   113	        checkInitialization(storedRules.initializationSuccessful(), "Cannot create rule store at %s", storedRulesFile.getAbsolutePath());
   114	    }
   115	
   116	    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
   117	        try {
   118	            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile));
   119	        } catch (IOException e) {
   120	            throw new StoreInitializationFailedException(e);
   121	        }
   122	    }
   123	
   124	    private File getStoredRulesFile() {
   125	        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
   126	        if (!rulesFile.exists() && !storeCreationAllowed) {
   127	            throw new StoreInitializationFailedException(String.format(
   128	                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
   129	                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
   130	        }
   131	        return rulesFile;
   132	    }
   133	
   134	    private void checkInitialization(boolean initializationSuccessful, String message, Object... args) {
   135	        if (!initializationSuccessful) {
   136	            throw new StoreInitializationFailedException(String.format(message, args));
   137	        }
   138	    }
   139	
   140	    @Override
   141	    public boolean contains(ArchRule rule) {
   142	        return storedRules.containsKey(rule.getDescription());
   143	    }
   144	
   145	    @Override
   146	    public void save(ArchRule rule, List<String> violations) {
   147	        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
   148	        if (!storeUpdateAllowed) {
   149	            throw new StoreUpdateFailedException(String.format(
   150	                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
   151	                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
   152	        }
   153	        String ruleFileName = ensureRuleFileName(rule);
   154	        write(violations, new File(storeFolder, ruleFileName));
   155	    }
   156	
   157	    private void write(List<String> violations, File ruleDetails) {
   158	        StringBuilder builder = new StringBuilder();
   159	        for (String violation : violations) {
   160	            builder.append(escape(violation)).append("\n");
   161	        }
   162	        try {
   163	            Files.write(ruleDetails.toPath(), builder.toString().getBytes(UTF_8));
   164	        } catch (IOException e) {
   165	            throw new StoreUpdateFailedException(e);
   166	        }
   167	    }
   168	
   169	    private String escape(String violation) {
   170	        return violation.replace("\n", "\\\n");
   171	    }
   172	
   173	    private String unescape(String violation) {
   174	        return violation.replace("\\\n", "\n");
   175	    }
   176	
   177	    private String ensureRuleFileName(ArchRule rule) {
   178	        String ruleDescription = rule.getDescription();
   179	        String candidateFileName = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
   180	        String existingFileName = storedRules.putIfAbsent(ruleDescription, candidateFileName);
   181	        if (existingFileName == null) {
   182	            log.trace("Assigning new file {} to rule '{}'", candidateFileName, ruleDescription);
   183	            return candidateFileName;
   184	        }
   185	        log.trace("Rule '{}' is already stored in file {}", ruleDescription, existingFileName);
   186	        return existingFileName;
   187	    }
   188	
   189	    @Override
   190	    public List<String> getViolations(ArchRule rule) {
   191	        String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
   192	        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
   193	        List<String> result = readLines(ruleDetailsFileName);
   194	        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
   195	        return result;
   196	    }
   197	
   198	    private List<String> readLines(String ruleDetailsFileName) {
   199	        String violationsText = readStoreFile(ruleDetailsFileName);
   200	        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
   201	                .map(this::unescape)
   202	                .collect(toList());
   203	    }
   204	
   205	    private String readStoreFile(String fileName) {
   206	        try {
   207	            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
   208	            return ensureUnixLineBreaks(result);
   209	        } catch (IOException e) {
   210	            throw new StoreReadException(e);
   211	        }
   212	    }
   213	
   214	    private static class FileSyncedProperties {
   215	        private final File propertiesFile;
   216	        private final Properties loadedProperties;
   217	
   218	        FileSyncedProperties(File file) {
   219	            propertiesFile = initializePropertiesFile(file);
   220	            loadedProperties = initializationSuccessful() ? loadRulesFrom(propertiesFile) : null;
   221	        }
   222	
   223	        boolean initializationSuccessful() {
   224	            return propertiesFile != null;
   225	        }
   226	
   227	        private File initializePropertiesFile(File file) {
   228	            try {
   229	                File directory = file.getParentFile();
   230	
   231	                // mkdirs() returns false both on failure and if another process concurrently
   232	                // created the directory, so isDirectory() distinguishes the two
   233	                if (!directory.mkdirs() && !directory.isDirectory()) {
   234	                    return null;
   235	                }
   236	
   237	                if (!file.exists() && !file.createNewFile()) {
   238	                    return null;
   239	                }
   240	
   241	                return file;
   242	            } catch (IOException e) {
   243	                return null;
   244	            }
   245	        }
   246	
   247	        private Properties loadRulesFrom(File file) {
   248	            Properties result = new Properties();
   249	            try (FileInputStream inputStream = new FileInputStream(file)) {
   250	                result.load(inputStream);
   251	            } catch (IOException e) {
   252	                throw new StoreInitializationFailedException(e);
   253	            }
   254	            return result;
   255	        }
   256	
   257	        boolean containsKey(String propertyName) {
   258	            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
   259	        }
   260	
   261	        String getProperty(String propertyName) {
   262	            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
   263	        }
   264	
   265	        synchronized String putIfAbsent(String key, String value) {
   266	            String normalizedKey = ensureUnixLineBreaks(key);
   267	            String existing = loadedProperties.getProperty(normalizedKey);
   268	            if (existing != null) {
   269	                return existing;
   270	            }
   271	            loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
   272	            syncFileSystem();
   273	            return null;
   274	        }
   275	
   276	        private void syncFileSystem() {
   277	            try (FileOutputStream outputStream = new FileOutputStream(propertiesFile)) {
   278	                loadedProperties.store(outputStream, "");
   279	            } catch (IOException e) {
   280	                throw new StoreUpdateFailedException(e);
   281	            }
   282	        }
   283	    }
   284	
   285	    /**
   286	     * Allows to adjust the rule violation file names of {@link TextFileBasedViolationStore}
   287	     *
   288	     * @see TextFileBasedViolationStore#TextFileBasedViolationStore(RuleViolationFileNameStrategy)
   289	     */
   290	    @FunctionalInterface
   291	    @PublicAPI(usage = INHERITANCE)
   292	    public interface RuleViolationFileNameStrategy {
   293	        /**
   294	         * Returns the file name to store violations of an {@link ArchRule}, possibly based on the rule description.<br>
   295	         * The returned names <b>must</b> be sufficiently unique from any others;
   296	         * as long as the descriptions themselves are unique, this can be achieved by sanitizing the description into some sort of file name.
   297	         *
   298	         * @param ruleDescription The description of the {@link ArchRule} to store
   299	         * @return The file name the respective rule violation file will have (see {@link TextFileBasedViolationStore})
   300	         */
   301	        String createRuleFileName(String ruleDescription);
   302	    }
   303	}

