   214	    private static class FileSyncedProperties {
   215	        private final File propertiesFile;
   216	        private final Properties loadedProperties;
   217	
   218	        FileSyncedProperties(File file) {
   219	            propertiesFile = initializePropertiesFile(file);
   220	            loadedProperties = initializationSuccessful() ? loadRulesFrom(propertiesFile) : null;
   221	        }
   222	
   223	        boolean initializationSuccessful() {
   224	            return propertiesFile != null;
   225	        }
   226	
   227	        private File initializePropertiesFile(File file) {
   228	            try {
   229	                File directory = file.getParentFile();
   230	
   231	                // mkdirs() returns false both on failure and if another process concurrently
   232	                // created the directory, so isDirectory() distinguishes the two
   233	                if (!directory.mkdirs() && !directory.isDirectory()) {
   234	                    return null;
   235	                }
   236	
   237	                if (!file.exists() && !file.createNewFile()) {
   238	                    return null;
   239	                }
   240	
   241	                return file;
   242	            } catch (IOException e) {
   243	                return null;
   244	            }
   245	        }
   246	
   247	        private Properties loadRulesFrom(File file) {
   248	            Properties result = new Properties();
   249	            try (FileInputStream inputStream = new FileInputStream(file)) {
   250	                result.load(inputStream);
   251	            } catch (IOException e) {
   252	                throw new StoreInitializationFailedException(e);
   253	            }
   254	            return result;
   255	        }
   256	
   257	        boolean containsKey(String propertyName) {
   258	            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
   259	        }
   260	
   261	        String getProperty(String propertyName) {
   262	            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
   263	        }
   264	
   265	        synchronized String putIfAbsent(String key, String value) {
   266	            String normalizedKey = ensureUnixLineBreaks(key);
   267	            String existing = loadedProperties.getProperty(normalizedKey);
   268	            if (existing != null) {
   269	                return existing;
   270	            }
   271	            loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
   272	            syncFileSystem();
   273	            return null;
   274	        }
