   276	        private void syncFileSystem() {
   277	            try (FileOutputStream outputStream = new FileOutputStream(propertiesFile)) {
   278	                loadedProperties.store(outputStream, "");
   279	            } catch (IOException e) {
   280	                throw new StoreUpdateFailedException(e);
   281	            }
   282	        }
