    private void repair() {
        synchronized (storedRules) {
            Map<String, String> fileNamesByRule = storedRules.reload();
            Set<String> sharedFileNames = findSharedFileNames(fileNamesByRule.values());

            List<String> brokenRules = new ArrayList<>();
            Map<String, RuleFile> resolvedRuleFiles = new LinkedHashMap<>();
            fileNamesByRule.forEach((ruleDescription, fileName) -> {
                if (sharedFileNames.contains(fileName)) {
                    return;
                }
                Optional<RuleFile> ruleFile = resolveRuleFile(fileName);
                if (!ruleFile.isPresent()) {
                    brokenRules.add(ruleDescription);
                } else if (ruleFile.get().isResolved()) {
                    resolvedRuleFiles.put(ruleDescription, ruleFile.get());
                }
            });
            if (brokenRules.isEmpty() && resolvedRuleFiles.isEmpty()) {
                return;
            }
            if (!storeUpdateAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Repairing violation store at %s is disabled (enable by configuration %s.%s=true)",
                        storeFolder.getAbsolutePath(), ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }

            List<String> discardedRules = new ArrayList<>();
            for (String ruleDescription : brokenRules) {
                log.info("Discarding broken entry of rule '{}' pointing to '{}'", ruleDescription, fileNamesByRule.get(ruleDescription));
                discardedRules.add(ruleDescription);
            }
            resolvedRuleFiles.forEach((ruleDescription, ruleFile) -> {
                try {
                    ruleFile.delete();
                    log.info("Discarded resolved rule '{}' stored in {}", ruleDescription, ruleFile);
                    discardedRules.add(ruleDescription);
                } catch (IOException e) {
                    log.warn("Cannot delete file {} of resolved rule '{}'", ruleFile, ruleDescription, e);
                }
            });
            storedRules.removeAll(discardedRules);
        }
    }

    /**
     * @return All file names that are pointed to by multiple entries,
     * either directly or because they denote the same file (e.g. through symbolic or hard links)
     */
    private Set<String> findSharedFileNames(Collection<String> ruleFileNames) {
        Set<String> result = new HashSet<>();
        Set<String> distinctFileNames = new LinkedHashSet<>();
        for (String fileName : ruleFileNames) {
            if (!distinctFileNames.add(fileName)) {
                result.add(fileName);
            }
        }

        Map<Object, List<String>> fileNamesByFile = new HashMap<>();
        for (String fileName : distinctFileNames) {
            resolveRuleFile(fileName).ifPresent(ruleFile -> {
                Object fileIdentity = ruleFile.identityAmong(fileNamesByFile.keySet());
                fileNamesByFile.computeIfAbsent(fileIdentity, __ -> new ArrayList<>()).add(fileName);
            });
        }
        fileNamesByFile.values().stream()
                .filter(fileNames -> fileNames.size() > 1)
                .forEach(result::addAll);
        return result;
    }

    /**
     * @return The rule violation file, if the file name denotes a regular file directly within the store folder,
     * otherwise the entry pointing to this file name is broken
     */
    private Optional<RuleFile> resolveRuleFile(String fileName) {
        Path folder = storeFolder.toPath();
        try {
            Path name = folder.getFileSystem().getPath(fileName);
            if (name.getRoot() != null || name.getNameCount() != 1 || !name.toString().equals(fileName)) {
                return Optional.empty();
            }
            Path path = folder.resolve(name);
            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class);
            return attributes.isRegularFile() ? Optional.of(new RuleFile(path, attributes.fileKey())) : Optional.empty();
        } catch (InvalidPathException | IOException e) {
            return Optional.empty();
        }
    }
