    private void forget(ArchRule rule) {
        String ruleDescription = rule.getDescription();
        synchronized (storedRules) {
            String fileName = storedRules.getProperty(ruleDescription);
            if (fileName == null) {
                log.trace("Rule '{}' without violations is not stored, nothing to forget", ruleDescription);
                return;
            }

            Optional<RuleFile> ruleFile = resolveRuleFile(fileName);
            if (ruleFile.isPresent() && !findSharedFileNames(storedRules.entries().values()).contains(fileName)) {
                try {
                    ruleFile.get().delete();
                } catch (IOException e) {
                    throw new StoreUpdateFailedException(String.format("Cannot delete file %s of rule '%s'", ruleFile.get(), ruleDescription), e);
                }
            }
            log.trace("Forgetting rule '{}' stored in file {}", ruleDescription, fileName);
            storedRules.removeAll(singletonList(ensureUnixLineBreaks(ruleDescription)));
        }
