package com.tngtech.archunit.library.freeze;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedList;
import java.util.List;
import java.util.Properties;

import com.google.common.collect.ImmutableList;
import com.tngtech.archunit.lang.ArchRule;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;
import static java.nio.charset.StandardCharsets.UTF_8;
import static java.util.Arrays.asList;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assumptions.assumeThat;

public class TextFileBasedViolationStoreIntegrityTest {

    @TempDir
    Path temporaryFolder;

    private Path storeFolder;
    private Path outsideFolder;

    @BeforeEach
    public void setUp() throws IOException {
        storeFolder = Files.createDirectory(temporaryFolder.resolve("store"));
        outsideFolder = Files.createDirectory(temporaryFolder.resolve("outside"));
    }

    @AfterEach
    public void restoreWritableStoreFolder() {
        storeFolder.toFile().setWritable(true);
    }

    @Test
    public void ignores_integrity_by_default() throws IOException {
        writeFile(storeFolder.resolve("resolved"), "");
        writeIndex("broken rule", "missing", "resolved rule", "resolved");

        ViolationStore store = initializedStore(storeProperties());

        assertThat(store.contains(rule("broken rule"))).isTrue();
        assertThat(store.contains(rule("resolved rule"))).isTrue();
        assertThat(readIndex()).containsOnlyKeys("broken rule", "resolved rule");
        assertThat(storeFolder.resolve("resolved")).exists();
    }

    @Test
    public void ignore_keeps_saving_empty_violations() throws IOException {
        ViolationStore store = initializedStore(storeProperties("default.integrity", "ignore"));

        store.save(rule("some rule"), ImmutableList.of());

        assertThat(store.contains(rule("some rule"))).isTrue();
        assertThat(store.getViolations(rule("some rule"))).isEmpty();
    }

    @Test
    public void rejects_unknown_integrity() {
        ViolationStore store = new TextFileBasedViolationStore();

        assertThatThrownBy(() -> store.initialize(storeProperties("default.integrity", "unknown")))
                .isInstanceOf(StoreInitializationFailedException.class)
                .hasMessageContaining("unknown")
                .hasMessageContaining("ignore, repair");
    }

    @Test
    public void repair_discards_broken_entries_without_touching_what_they_point_to() throws IOException {
        Files.createDirectory(storeFolder.resolve("directory"));
        Files.createDirectory(storeFolder.resolve("sub"));
        writeFile(storeFolder.resolve("sub").resolve("nested"), "violation");
        writeFile(outsideFolder.resolve("outside"), "violation");
        Files.createSymbolicLink(storeFolder.resolve("dangling"), storeFolder.resolve("nowhere"));
        Files.createSymbolicLink(storeFolder.resolve("directoryLink"), outsideFolder);
        writeFile(storeFolder.resolve("valid"), "violation");
        writeIndex(
                "missing rule", "missing",
                "directory rule", "directory",
                "nested rule", "sub/nested",
                "parent rule", "../outside/outside",
                "absolute rule", outsideFolder.resolve("outside").toAbsolutePath().toString(),
                "dangling rule", "dangling",
                "directory link rule", "directoryLink",
                "empty rule", "",
                "invalid rule", "invalid\0name",
                "valid rule", "valid");

        ViolationStore store = initializedStore(repairProperties());

        assertThat(readIndex()).containsOnlyKeys("valid rule");
        assertThat(store.contains(rule("missing rule"))).isFalse();
        assertThat(store.getViolations(rule("valid rule"))).containsExactly("violation");
        assertThat(storeFolder.resolve("directory")).isDirectory();
        assertThat(storeFolder.resolve("sub").resolve("nested")).hasContent("violation");
        assertThat(outsideFolder.resolve("outside")).hasContent("violation");
        assertThat(Files.isSymbolicLink(storeFolder.resolve("dangling"))).isTrue();
        assertThat(Files.isSymbolicLink(storeFolder.resolve("directoryLink"))).isTrue();
        assertThat(outsideFolder).isDirectory();
    }

    @Test
    public void repair_discards_resolved_entries_and_their_files() throws IOException {
        writeFile(storeFolder.resolve("empty"), "");
        writeFile(storeFolder.resolve("lineBreaks"), "\n\r\n\n");
        writeFile(storeFolder.resolve("valid"), "violation");
        writeIndex(
                "empty rule", "empty",
                "line breaks rule", "lineBreaks",
                "valid rule", "valid");

        ViolationStore store = initializedStore(repairProperties());

        assertThat(readIndex()).containsOnlyKeys("valid rule");
        assertThat(store.contains(rule("empty rule"))).isFalse();
        assertThat(store.contains(rule("line breaks rule"))).isFalse();
        assertThat(storeFolder.resolve("empty")).doesNotExist();
        assertThat(storeFolder.resolve("lineBreaks")).doesNotExist();
        assertThat(storeFolder.resolve("valid")).hasContent("violation");
    }

    @Test
    public void repair_deletes_target_of_resolved_symbolic_link() throws IOException {
        Path target = writeFile(outsideFolder.resolve("target"), "\n");
        Files.createSymbolicLink(storeFolder.resolve("link"), target);
        writeIndex("resolved rule", "link");

        initializedStore(repairProperties());

        assertThat(readIndex()).isEmpty();
        assertThat(storeFolder.resolve("link")).doesNotExist();
        assertThat(Files.isSymbolicLink(storeFolder.resolve("link"))).isFalse();
        assertThat(target).doesNotExist();
    }

    @Test
    public void repair_does_not_touch_entries_sharing_the_same_file_name() throws IOException {
        writeFile(storeFolder.resolve("resolved"), "");
        writeIndex(
                "first missing rule", "missing",
                "second missing rule", "missing",
                "first resolved rule", "resolved",
                "second resolved rule", "resolved");

        initializedStore(repairProperties());

        assertThat(readIndex()).containsOnlyKeys("first missing rule", "second missing rule", "first resolved rule", "second resolved rule");
        assertThat(storeFolder.resolve("resolved")).exists();
    }

    @Test
    public void repair_does_not_touch_entries_sharing_the_same_file_through_links() throws IOException {
        writeFile(storeFolder.resolve("resolved"), "");
        Files.createSymbolicLink(storeFolder.resolve("symbolicLink"), storeFolder.resolve("resolved"));
        writeFile(storeFolder.resolve("otherResolved"), "");
        createHardLinkOrSkip(storeFolder.resolve("hardLink"), storeFolder.resolve("otherResolved"));
        Path outsideTarget = writeFile(outsideFolder.resolve("outsideResolved"), "");
        Files.createSymbolicLink(storeFolder.resolve("firstOutsideLink"), outsideTarget);
        Files.createSymbolicLink(storeFolder.resolve("secondOutsideLink"), outsideTarget);
        writeIndex(
                "file rule", "resolved",
                "symbolic link rule", "symbolicLink",
                "other file rule", "otherResolved",
                "hard link rule", "hardLink",
                "first outside rule", "firstOutsideLink",
                "second outside rule", "secondOutsideLink");

        initializedStore(repairProperties());

        assertThat(readIndex()).containsOnlyKeys(
                "file rule", "symbolic link rule", "other file rule", "hard link rule", "first outside rule", "second outside rule");
        assertThat(storeFolder.resolve("resolved")).exists();
        assertThat(storeFolder.resolve("symbolicLink")).exists();
        assertThat(storeFolder.resolve("otherResolved")).exists();
        assertThat(storeFolder.resolve("hardLink")).exists();
        assertThat(outsideTarget).exists();
    }

    @Test
    public void repair_keeps_shared_broken_entries_although_other_entries_are_valid() throws IOException {
        writeFile(storeFolder.resolve("valid"), "violation");
        Files.createSymbolicLink(storeFolder.resolve("validLink"), storeFolder.resolve("valid"));
        writeIndex(
                "valid rule", "valid",
                "valid link rule", "validLink",
                "first broken rule", "sub/missing",
                "second broken rule", "sub/missing");

        initializedStore(repairProperties());

        assertThat(readIndex()).containsOnlyKeys("valid rule", "valid link rule", "first broken rule", "second broken rule");
    }

    @Test
    public void repair_does_not_touch_files_no_entry_points_to() throws IOException {
        writeFile(storeFolder.resolve("unreferencedEmpty"), "");
        writeFile(storeFolder.resolve("unreferenced"), "violation");
        writeIndex("missing rule", "missing");

        initializedStore(repairProperties());

        assertThat(readIndex()).isEmpty();
        assertThat(storeFolder.resolve("unreferencedEmpty")).exists();
        assertThat(storeFolder.resolve("unreferenced")).hasContent("violation");
    }

    @Test
    public void repair_checks_store_on_disk_even_if_initialized_before() throws IOException {
        ViolationStore firstStore = initializedStore(repairProperties());
        firstStore.save(rule("some rule"), ImmutableList.of("violation"));
        String fileName = readIndex().getProperty("some rule");
        writeFile(storeFolder.resolve(fileName), "");

        ViolationStore secondStore = initializedStore(repairProperties());

        assertThat(secondStore.contains(rule("some rule"))).isFalse();
        assertThat(firstStore.contains(rule("some rule"))).isFalse();
        assertThat(readIndex()).isEmpty();
        assertThat(storeFolder.resolve(fileName)).doesNotExist();

        Properties index = readIndex();
        index.setProperty("other rule", "missing");
        writeIndex(index);

        initializedStore(repairProperties());

        assertThat(readIndex()).isEmpty();
    }

    @Test
    public void repair_is_rejected_if_store_update_is_disabled() throws IOException {
        writeIndex("missing rule", "missing");
        ViolationStore store = new TextFileBasedViolationStore();

        assertThatThrownBy(() -> store.initialize(repairProperties("default.allowStoreUpdate", "false")))
                .isInstanceOf(StoreInitializationFailedException.class)
                .hasMessageContaining("default.allowStoreUpdate");

        assertThat(readIndex()).containsOnlyKeys("missing rule");
    }

    @Test
    public void repair_forgets_rule_when_saving_no_violations() throws IOException {
        ViolationStore store = initializedStore(repairProperties());
        store.save(rule("some rule"), ImmutableList.of("violation"));
        store.save(rule("other rule"), ImmutableList.of("other violation"));
        String fileName = readIndex().getProperty("some rule");

        store.save(rule("some rule"), ImmutableList.of());

        assertThat(store.contains(rule("some rule"))).isFalse();
